#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <direct.h>
#include "tournament.h"
#include "team.h"
#include "scheduler.h"
#include "match.h"
#include "standings.h"
#include "storage.h"
#include "auth.h"
#define CHECK(x) do{if(!(x)){printf("FAIL: %s (line %d)\n",#x,__LINE__);return 1;}}while(0)
static int schedule_tests(void){int n;for(n=2;n<=8;n++){TournamentStore s;Tournament*t;char e[128];int i;store_init(&s);t=tournament_create(&s,1,"Test","",e,sizeof e);for(i=0;i<n;i++){char x[20];sprintf(x,"Team%d",i);CHECK(team_add(t,x,"","",e,sizeof e));}CHECK(schedule_generate(t,e,sizeof e));CHECK(t->rounds==(n%2?n:n-1));CHECK(schedule_validate(t,e,sizeof e));store_free(&s);}return 0;}
static int auth_tests(void){AuthStore users={0};AuthUser*admin=NULL,*viewer=NULL;char err[128]={0};char token[AUTH_TOKEN_LEN];users.next_user_id=1;CHECK(auth_setup_required(&users));if(!auth_create_user(&users,"Admin.One","Tournament Admin","CorrectHorse123!",AUTH_ROLE_ADMIN,&admin,err,sizeof err)){fprintf(stderr,"Could not create test account: %s\n",err);return 1;}CHECK(!auth_setup_required(&users));CHECK(auth_find_username(&users,"ADMIN.ONE")==admin);CHECK(auth_verify_password(admin,"CorrectHorse123!"));CHECK(!auth_verify_password(admin,"incorrect"));CHECK(!auth_create_user(&users,"admin.one","Duplicate","CorrectHorse123!",AUTH_ROLE_VIEWER,NULL,err,sizeof err));CHECK(auth_create_user(&users,"match-viewer","Match Viewer","AnotherPass123!",AUTH_ROLE_VIEWER,&viewer,err,sizeof err));CHECK(auth_create_session(&users,admin->id,token));CHECK(auth_find_session(&users,token)==admin);CHECK(!auth_update_user(&users,admin,NULL,NULL,1,AUTH_ROLE_VIEWER,err,sizeof err));CHECK(!auth_delete_user(&users,admin,err,sizeof err));CHECK(auth_update_user(&users,admin,NULL,"ReplacementPass123!",0,AUTH_ROLE_ADMIN,err,sizeof err));CHECK(auth_find_session(&users,token)==NULL);CHECK(auth_verify_password(admin,"ReplacementPass123!"));CHECK(!auth_verify_password(admin,"CorrectHorse123!"));CHECK(auth_create_session(&users,admin->id,token));CHECK(auth_find_session(&users,token)==admin);auth_revoke_session(&users,token);CHECK(auth_find_session(&users,token)==NULL);CHECK(auth_delete_user(&users,viewer,err,sizeof err));return 0;}
int main(void){TournamentStore s,s2;Tournament*t;char e[128];size_t n;Standing*x;_mkdir("data");CHECK(schedule_tests()==0);CHECK(auth_tests()==0);store_init(&s);t=tournament_create(&s,7,"Cup","",e,sizeof e);CHECK(t->owner_id==7);CHECK(tournament_find_owned(&s,t->id,7)==t);CHECK(tournament_find_owned(&s,t->id,8)==NULL);CHECK(team_add(t,"A","","",e,sizeof e));CHECK(team_add(t,"B","","",e,sizeof e));CHECK(schedule_generate(t,e,sizeof e));CHECK(!match_set_result(t,999,1,0,e,sizeof e));CHECK(match_set_result(t,t->matches[0].id,2,1,e,sizeof e));x=standings_calculate(t,&n);CHECK(n==2&&x[0].points==3);free(x);CHECK(storage_save(&s,"data/test.bin",e,sizeof e));store_init(&s2);CHECK(storage_load(&s2,"data/test.bin",e,sizeof e));CHECK(s2.head&&s2.head->tournament.team_count==2&&s2.head->tournament.owner_id==7);store_free(&s);store_free(&s2);printf("All tournament, authentication, ownership, and storage tests passed.\n");return 0;}
